"""field_report.py : writes docs/field_proposals.md (observed ranges, candidate fields with evidence counts, PROPOSED fields.json changes; nothing is applied)."""
import sys, os, io, collections, contextlib; sys.path.insert(0, os.path.dirname(__file__))
import corpus
recs = corpus.load(); N = len(recs); L = lambda r, p: r["leaves"].get(p); P = "/PlayRecordData/"
ce = lambda r: L(r, P + "current_end_"); tut = lambda r: int(L(r, P + "is_new_game_plus_tutorial_compl")); d = lambda r, i: int(L(r, P + f"difficulty_clear_flag_/{i}"))
G = collections.OrderedDict(); [G.setdefault(corpus.group(r), []).append(r) for r in recs]
cnt = lambda f: sum(1 for r in recs if f(r))
buf = io.StringIO()
with contextlib.redirect_stdout(buf):
    import runpy; runpy.run_path(os.path.join(os.path.dirname(__file__), "field_stats.py"), run_name="__main__")
ranges = "\n".join(l[:200] for l in buf.getvalue().splitlines() if l.strip() and not l.startswith("fields with"))
diff_ms = sorted(r["hdr"]["play"] - L(r, "/PlayerData/total_play_time") for r in recs)
d3 = [r for r in recs if d(r, 3)]; d0 = [r for r in recs if d(r, 0)]
def dist(g, f): return ", ".join(f"{k}: {v}" for k, v in sorted(collections.Counter(f(r) for r in G[g]).items()))
